procedural_water_vfx:
shader_type spatial;
render_mode unshaded, cull_disabled, depth_draw_never, blend_mix, shadows_disabled;

uniform vec4 tint : source_color = vec4(0.4, 0.9, 1.0, 1.0);
uniform float alpha_multiplier : hint_range(0.0, 1.0) = 1.0;
uniform float phase = 0.0;
uniform float flow_speed = 1.0;
uniform int shape_mode = 0; // 0 stream, 2 ring, 3 mist, 4 wave wall, 5 curved wave footprint

float hash21(vec2 p) { return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453); }
float soft(float edge0, float edge1, float x) { return smoothstep(edge0, edge1, x); }
vec3 vivid_color(vec3 color) {
    float luminance = dot(color, vec3(0.299, 0.587, 0.114));
    return clamp(mix(vec3(luminance), color, 1.22) * 1.04, 0.0, 1.0);
}

void fragment() {
    vec2 p = UV * 2.0 - 1.0;
    float time = TIME * flow_speed + phase;
    float a = 0.0;
    if (shape_mode == 0) {
        // A clean pressure spear: straight, tapered and never jagged.
        float thickness = mix(0.16, 0.34, 1.0 - abs(p.x));
        a = 1.0 - soft(thickness, thickness + 0.12, abs(p.y));
        // Never reverse smoothstep edges: the result is undefined on mobile GPUs.
        a *= 1.0 - soft(0.78, 1.02, abs(p.x));
    } else if (shape_mode == 1) {
        a = 0.0; // Ribbon mode deliberately disabled: it caused the shared spiky silhouette.
    } else if (shape_mode == 2) {
        float r = length(p);
        // Clean pressure/ripple ring. The old angular multiplier created the
        // unwanted seven-spoke shape shared by all three Water EVO paths.
        a = 1.0 - soft(0.18, 0.34, abs(r - (0.42 + sin(time * 5.0) * 0.05)));
    } else if (shape_mode == 3) {
        float n = hash21(floor((p + time * 0.13) * 13.0));
        a = (1.0 - smoothstep(0.28, 1.08, length(p))) * (0.35 + n * 0.65);
    } else if (shape_mode == 4) {
        float crest = 0.25 + sin(p.x * 10.0 - time * 4.0) * 0.12 + sin(p.x * 23.0 + time * 3.0) * 0.04;
        float body = soft(-0.92, -0.58, p.y) * (1.0 - soft(crest, crest + 0.16, p.y));
        float foam = 1.0 - soft(0.05, 0.20, abs(p.y - crest));
        a = max(body * 0.74, foam);
    } else {
        // A bowed front seen from above. Local X is travel depth and local Y
        // spans the wide crest, so this reads as a wave rather than a circle.
        float bowed_front = p.x - (0.22 - p.y * p.y * 0.34);
        float band = 1.0 - soft(0.06, 0.20, abs(bowed_front));
        float side_fade = 1.0 - soft(0.78, 1.02, abs(p.y));
        float broken_foam = 0.78 + 0.22 * sin(p.y * 17.0 - time * 3.0);
        a = band * side_fade * broken_foam;
    }
    a = clamp(a, 0.0, 1.0);
    vec3 color = vivid_color(tint.rgb);
    ALBEDO = color;
	EMISSION = color * 0.28;
	// Coverage defines the silhouette; source tint alpha no longer makes the
	// whole skill look like a translucent decal.
	ALPHA = smoothstep(0.08, 0.24, a) * alpha_multiplier * 0.88;
}

tidal_wave_surface:
shader_type spatial;
render_mode unshaded, cull_disabled, depth_draw_never, blend_mix, shadows_disabled;

uniform vec4 base_color : source_color = vec4(0.16, 0.62, 0.96, 0.82);
uniform float alpha_multiplier : hint_range(0.0, 1.0) = 1.0;
uniform float flow_speed = 1.0;
uniform float phase_offset = 0.0;
uniform float life_progress : hint_range(0.0, 1.0) = 0.0;
uniform float foam_layer : hint_range(0.0, 1.0) = 0.0;

float hash21(vec2 p) {
	return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453);
}

vec3 vivid_color(vec3 color) {
	float luminance = dot(color, vec3(0.299, 0.587, 0.114));
	return clamp(mix(vec3(luminance), color, 1.22) * 1.04, 0.0, 1.0);
}

void vertex() {
	float time = TIME * flow_speed + phase_offset;
	float crest_weight = smoothstep(0.48, 1.0, UV.y);
	float center_weight = sin(UV.x * 3.14159265);
	float rolling = sin(UV.x * 12.0 - time * 5.4 + UV.y * 2.8);
	float cross_flow = sin(UV.x * 23.0 + time * 3.1 + UV.y * 5.0);
	float break_cycle = 0.5 + 0.5 * sin(time * 4.2 + UV.x * 5.5);
	VERTEX.y += rolling * (0.035 + crest_weight * 0.105) * center_weight;
	VERTEX.y += cross_flow * crest_weight * 0.025;
	VERTEX.z += crest_weight * (0.10 + break_cycle * 0.16);
	VERTEX.z += sin(time * 3.6 + UV.x * 8.0) * (0.018 + crest_weight * 0.045);
	float collapse = smoothstep(0.76, 1.0, life_progress);
	VERTEX.y *= mix(1.0, 0.38, collapse);
	VERTEX.z += collapse * crest_weight * 0.20;
}

void fragment() {
	float time = TIME * flow_speed + phase_offset;
	float broad_wash = 0.5 + 0.5 * sin(UV.x * 9.0 - time * 2.4 + sin(UV.y * 7.0) * 1.2);
	float fine_wash = hash21(floor(UV * vec2(48.0, 34.0) + phase_offset));
	float crest = smoothstep(0.55, 1.0, UV.y);
	float broken_edge = 0.78 + 0.22 * sin(UV.x * 31.0 + time * 4.0);
	float side_fade = smoothstep(0.0, 0.22, UV.x) * smoothstep(0.0, 0.22, 1.0 - UV.x);
	float back_fade = smoothstep(0.0, 0.10, UV.y);
	float front_fade = 1.0 - smoothstep(0.90, 1.0, UV.y);
	float torn_sides = smoothstep(0.12, 0.52, broad_wash + fine_wash * 0.24);
	vec3 deep_color = base_color.rgb * vec3(0.70, 0.84, 1.0);
	vec3 bright_color = mix(base_color.rgb, vec3(0.92, 1.0, 1.0), 0.50 + foam_layer * 0.34);
	vec3 color = mix(deep_color, bright_color, crest * 0.68 + broad_wash * 0.20 + foam_layer * 0.30);
	color = vivid_color(color * (0.91 + fine_wash * 0.09));
	float painted_alpha = (0.78 + broad_wash * 0.14 + fine_wash * 0.08);
	painted_alpha *= mix(1.0, broken_edge, crest * (0.46 + foam_layer * 0.42));
	ALBEDO = color;
	EMISSION = color * mix(0.08, 0.20, crest + foam_layer * 0.35);
	float edge_mask = side_fade * back_fade * front_fade;
	edge_mask *= mix(0.78, 1.0, torn_sides);
	ALPHA = smoothstep(0.08, 0.24, painted_alpha * edge_mask) * alpha_multiplier * 0.86;
}

frost_breath:
shader_type spatial;
render_mode unshaded, cull_disabled, depth_draw_never, blend_mix, shadows_disabled;

uniform vec4 base_color : source_color = vec4(0.56, 0.86, 1.0, 0.52);
uniform vec4 frost_color : source_color = vec4(0.92, 0.99, 1.0, 0.76);
uniform float alpha_multiplier : hint_range(0.0, 1.0) = 1.0;
uniform float flow_speed = 1.0;
uniform float phase = 0.0;

vec3 vivid_color(vec3 color) {
	float luminance = dot(color, vec3(0.299, 0.587, 0.114));
	return clamp(mix(vec3(luminance), color, 1.18) * 1.04, 0.0, 1.0);
}

void vertex() {
	float time = TIME * flow_speed + phase;
	float length_weight = UV.y;
	VERTEX.x += sin(time * 3.8 + UV.y * 10.0 + UV.x * 5.0) * length_weight * 0.055;
	VERTEX.y += sin(time * 4.6 - UV.y * 12.0 + UV.x * 8.0) * length_weight * 0.028;
}

void fragment() {
	float time = TIME * flow_speed + phase;
	float side_fade = smoothstep(0.0, 0.18, UV.x) * smoothstep(0.0, 0.18, 1.0 - UV.x);
	float start_fade = smoothstep(0.0, 0.10, UV.y);
	float end_fade = 1.0 - smoothstep(0.82, 1.0, UV.y);
	float broad = 0.5 + 0.5 * sin(UV.x * 15.0 - time * 3.7 + UV.y * 17.0);
	float fine = 0.5 + 0.5 * sin(UV.x * 31.0 + time * 2.8 - UV.y * 27.0 + phase);
	float mist = smoothstep(0.08, 0.90, broad * 0.68 + fine * 0.32);
	vec3 color = vivid_color(mix(base_color.rgb, frost_color.rgb, mist * 0.58 + UV.y * 0.20));
	ALBEDO = color;
	EMISSION = color * (0.14 + mist * 0.10);
	float coverage = side_fade * start_fade * end_fade * (0.42 + mist * 0.58);
	ALPHA = smoothstep(0.10, 0.28, coverage) * alpha_multiplier;
}

ice_crystal:
shader_type spatial;
render_mode unshaded, cull_disabled, depth_draw_never, blend_mix, shadows_disabled;

uniform vec4 base_color : source_color = vec4(0.48, 0.82, 1.0, 0.82);
uniform vec4 edge_color : source_color = vec4(0.92, 0.99, 1.0, 0.94);
uniform float alpha_multiplier : hint_range(0.0, 1.0) = 1.0;
uniform float emission_strength = 1.0;
uniform float phase = 0.0;

vec3 vivid_color(vec3 color) {
	float luminance = dot(color, vec3(0.299, 0.587, 0.114));
	return clamp(mix(vec3(luminance), color, 1.20) * 1.04, 0.0, 1.0);
}

void fragment() {
	float facing = clamp(dot(normalize(NORMAL), normalize(VIEW)), 0.0, 1.0);
	float fresnel = pow(1.0 - facing, 1.35);
	float height = UV.y;
	float facet = floor((0.5 + 0.5 * sin(UV.x * 25.1327 + phase)) * 3.0) / 3.0;
	float painted = 0.5 + 0.5 * sin(UV.x * 12.5664 + height * 8.0 + phase);
	vec3 color = mix(base_color.rgb * (0.78 + facet * 0.18), edge_color.rgb, fresnel * 0.58 + height * 0.18);
	color = vivid_color(color * (0.94 + painted * 0.08));
	ALBEDO = color;
	EMISSION = color * emission_strength * (0.20 + fresnel * 0.10);
	ALPHA = alpha_multiplier;
}

boundary_ripple:
shader_type spatial;
render_mode unshaded, cull_disabled, blend_mix, depth_draw_never;

uniform vec4 ring_color : source_color = vec4(0.72, 0.96, 1.0, 0.78);
uniform float progress : hint_range(0.0, 1.0) = 0.0;
uniform float phase = 0.0;
uniform float edge_variation : hint_range(0.0, 0.04) = 0.012;
uniform float band_width : hint_range(0.02, 0.12) = 0.06;

float hash21(vec2 p) {
	return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453);
}

vec3 vivid_color(vec3 color) {
	float luminance = dot(color, vec3(0.299, 0.587, 0.114));
	return clamp(mix(vec3(luminance), color, 1.24) * 1.04, 0.0, 1.0);
}

void fragment() {
	vec2 centered_uv = (UV - vec2(0.5)) * 2.0;
	float distance_from_center = length(centered_uv);
	float angle = atan(centered_uv.y, centered_uv.x);
	float ring_radius = mix(0.12, 0.92, progress);
	float soft_motion = sin(angle * 3.0 + TIME * 3.1 + phase) * 0.58;
	soft_motion += sin(angle * 5.0 - TIME * 2.2 + phase * 1.7) * 0.24;
	float painted_radius = ring_radius + soft_motion * edge_variation;
	float ring = 1.0 - smoothstep(band_width * 0.42, band_width, abs(distance_from_center - painted_radius));
	float wash = mix(0.88, 1.0, hash21(floor(UV * 72.0 + phase)));
	// Keep a large warning band visible on the bright forest floor.
	float fade = 1.0 - smoothstep(0.54, 1.0, progress);
	vec3 painted_color = vivid_color(mix(ring_color.rgb * 0.88, ring_color.rgb, wash));
	ALBEDO = painted_color;
	EMISSION = painted_color * 0.12;
	ALPHA = smoothstep(0.10, 0.30, ring * wash) * fade;
}

stylized_procedural_vfx:
shader_type spatial;
render_mode unshaded, cull_disabled, depth_draw_never, blend_mix, shadows_disabled;

uniform vec4 base_color : source_color = vec4(0.3, 0.8, 1.0, 1.0);
uniform vec4 edge_color : source_color = vec4(0.9, 1.0, 1.0, 1.0);
uniform float alpha_multiplier : hint_range(0.0, 1.0) = 1.0;
uniform float emission_strength : hint_range(0.0, 3.0) = 1.25;
uniform float pulse_strength : hint_range(0.0, 0.2) = 0.04;
uniform float flow_speed = 1.0;
uniform float phase = 0.0;

vec3 vivid_color(vec3 color) {
	float luminance = dot(color, vec3(0.299, 0.587, 0.114));
	return clamp(mix(vec3(luminance), color, 1.16) * 1.02, 0.0, 1.0);
}

void vertex() {
    float pulse = sin(TIME * flow_speed * 4.0 + phase + VERTEX.y * 7.0) * pulse_strength;
    VERTEX.xz *= 1.0 + pulse;
}

void fragment() {
    float facing = clamp(dot(normalize(NORMAL), normalize(VIEW)), 0.0, 1.0);
    float fresnel = pow(1.0 - facing, 1.7);
    float flow = 0.5 + 0.5 * sin(UV.y * 12.0 - TIME * flow_speed * 3.0 + phase);
    float wash = 0.5 + 0.5 * sin(UV.x * 9.0 + sin(UV.y * 7.0 + phase) * 1.8);
    float paper_variation = 0.92 + wash * 0.08;
    float edge_mix = clamp(fresnel * 0.72 + flow * 0.12 + wash * 0.08, 0.0, 1.0);
    vec3 color = mix(base_color.rgb, edge_color.rgb, edge_mix);
    color *= paper_variation;
    vec3 cel_color = floor(color * 6.0 + 0.5) / 6.0;
    color = vivid_color(mix(color, cel_color, 0.24));
    ALBEDO = color;
	// Strong albedo and restrained emission keep the elemental hue instead of
	// turning pale on the bright grass stage.
	EMISSION = color * emission_strength * (0.16 + flow * 0.06);
	ALPHA = clamp(alpha_multiplier * (0.58 + fresnel * 0.12 + wash * 0.03), 0.0, 0.84);
}
